/**
 * `ouaf pack-alpha` with the real ffmpeg, on synthetic inputs generated by ffmpeg itself (no image of anyone).
 * Reported as skipped, with the reason in its name, when ffmpeg is not installed: the unit tests in
 * pack-alpha.test.ts do not need it.
 */
import { execFileSync } from 'node:child_process'
import { mkdir, mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { EXIT } from '../src/command.ts'
import { createPackAlpha } from '../src/commands/pack-alpha.ts'
import { spawnRunner } from '../src/ffmpeg.ts'

const FFMPEG = process.env.OUAF_FFMPEG ?? 'ffmpeg'

function hasFfmpeg(): boolean {
  try {
    const encoders = execFileSync(FFMPEG, ['-hide_banner', '-encoders'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })
    execFileSync(FFMPEG.replace(/ffmpeg(?=[^\\/]*$)/i, 'ffprobe'), ['-version'], { stdio: 'ignore' })
    return /\slibx264\s/.test(encoders) && /\slibvpx-vp9\s/.test(encoders) && /\sprores_ks\s/.test(encoders)
  } catch {
    return false
  }
}

const available = hasFfmpeg()
const SKIPPED = 'ffmpeg (with ffprobe, libx264, libvpx-vp9, prores_ks) not found: install it or set OUAF_FFMPEG'
if (!available) process.stderr.write(`\npack-alpha.ffmpeg.test.ts: SKIPPED, ${SKIPPED}\n`)

/**
 * Source: 128×128, red disc (r < 0.42) on blue; alpha 255 inside r < 0.3, 128 in the ring 0.3–0.42, 0 outside (where
 * the blue must never show).
 */
const R = 'hypot(X-W/2,Y-H/2)/H'
const SOURCE = `nullsrc=s=128x128:r=10:d=1,format=rgba,geq=r='if(lt(${R},0.42),255,0)':g=0:b='if(lt(${R},0.42),0,255)':` +
  `a='if(lt(${R},0.3),255,if(lt(${R},0.42),128,0))'`

type RGB = [number, number, number]

/** First frame of an MP4, decoded by ffmpeg to RGB. */
function firstFrame(file: string): { width: number; height: number; at: (x: number, y: number) => RGB } {
  const probe = JSON.parse(execFileSync(FFMPEG.replace(/ffmpeg(?=[^\\/]*$)/i, 'ffprobe'),
    ['-v', 'error', '-show_entries', 'stream=width,height,codec_name,profile,pix_fmt', '-of', 'json', file], { encoding: 'utf8' }))
  const { width, height, codec_name: codec, pix_fmt: pixFmt } = probe.streams[0]
  expect([codec, pixFmt]).toEqual(['h264', 'yuv420p'])
  const rgb = execFileSync(FFMPEG, ['-v', 'error', '-i', file, '-frames:v', '1', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'])
  return { width, height, at: (x, y) => [...rgb.subarray((y * width + x) * 3, (y * width + x) * 3 + 3)] as RGB }
}

const near = (c: RGB, e: RGB, tolerance = 12) => c.every((v, i) => Math.abs(v - e[i]!) <= tolerance)

describe('pack-alpha with ffmpeg', () => {
  let dir: string | undefined
  beforeAll(async () => {
    if (!available) return
    dir = await mkdtemp(join(tmpdir(), 'ouaf-pack-alpha-ffmpeg-'))
    const gen = (args: string[]) => execFileSync(FFMPEG, ['-v', 'error', '-y', '-f', 'lavfi', '-i', SOURCE, ...args])
    gen(['-c:v', 'libvpx-vp9', '-pix_fmt', 'yuva420p', '-b:v', '0', '-crf', '20', join(dir, 'src.webm')])
    gen(['-c:v', 'prores_ks', '-profile:v', '4444', '-pix_fmt', 'yuva444p10le', join(dir, 'src.mov')])
    await mkdir(join(dir, 'frames'))
    gen([join(dir, 'frames', 'f_%03d.png')])
  })
  afterAll(async () => {
    if (dir) await rm(dir, { recursive: true, force: true })
  })

  for (const input of ['src.webm', 'src.mov', 'frames']) {
    it(`packs ${input}: color left, alpha mask right`, async ({ skip }) => {
      if (!available) return skip(SKIPPED)
      const output = join(dir!, `${input}.mp4`)
      const log: string[] = []
      const code = await createPackAlpha({ runner: spawnRunner, env: { OUAF_FFMPEG: FFMPEG } })
        .run([join(dir!, input), '-o', output, '--fps', '10'], { out: (t) => log.push(t), err: (t) => log.push(t) })
      expect(code, log.join('\n')).toBe(EXIT.OK)
      const f = firstFrame(output)
      expect([f.width, f.height]).toEqual([256, 128])
      const c = 64 // centre of the color half; the mask half starts at x = 128
      const ring = c + 46 // 0.36 · 128 from the centre
      expect(f.at(c, c), 'color, opaque').toSatisfy((v: RGB) => near(v, [255, 0, 0]))
      expect(f.at(ring, c), 'color, ring').toSatisfy((v: RGB) => near(v, [255, 0, 0]))
      expect(f.at(128 + c, c), 'mask, opaque').toSatisfy((v: RGB) => near(v, [255, 255, 255]))
      expect(f.at(128 + ring, c), 'mask, ring').toSatisfy((v: RGB) => near(v, [128, 128, 128]))
      expect(f.at(128 + 4, 4), 'mask, transparent').toSatisfy((v: RGB) => near(v, [0, 0, 0], 4))
      // Where the source is transparent, its blue must not leak into the color half.
      expect(f.at(4, 4)[2], 'color, transparent').toBeLessThan(40)
    })
  }
})
